    {
      "role": "tool",
      "content": "name: Atoma Entry\n\non:\n  issues:\n    types: [opened]\n\npermissions:\n  actions: write\n  issues: write\n  pull-requests: write\n  contents: write\n\njobs:\n  route:\n    runs-on: ubuntu-latest\n    outputs:\n      agent: ${{ steps.resolve.outputs.agent }}\n      number: ${{ steps.resolve.outputs.number }}\n      type: ${{ steps.resolve.outputs.type }}\n      notify: ${{ steps.resolve.outputs.notify }}\n    steps:\n      - name: Resolve agent and context\n        id: resolve\n        shell: bash\n        env:\n          NUMBER: ${{ github.event.issue.number }}\n          SENDER: ${{ github.event.sender.login }}\n        run: |\n          AGENT=\"\"\n          FIRST_LINE=$(python3 -c \"import json,sys; b=json.load(sys.stdin).get('issue',{}).get('body',''); print(b.strip().split(chr(10))[0] if b else '')\" < \"$GITHUB_EVENT_PATH\")\n          case \"$FIRST_LINE\" in\n            /*) AGENT=\"${FIRST_LINE#/}\" ;;\n          esac\n          if [ -z \"$AGENT\" ]; then\n            exit 0\n          fi\n          echo \"agent=${AGENT}\" >> \"$GITHUB_OUTPUT\"\n          echo \"number=${NUMBER}\" >> \"$GITHUB_OUTPUT\"\n          echo \"type=issue\" >> \"$GITHUB_OUTPUT\"\n          echo \"notify=${SENDER}\" >> \"$GITHUB_OUTPUT\"\n\n      - name: Add reaction to issue\n        if: steps.resolve.outputs.agent != ''\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          NUMBER: ${{ github.event.issue.number }}\n        run: |\n          gh api --method POST \"repos/${GITHUB_REPOSITORY}/issues/${NUMBER}/reactions\" -f content=\"eyes\" 2>/dev/null || true\n\n  run:\n    needs: route\n    if: needs.route.outputs.agent != ''\n    uses: ./.github/workflows/atoma-runner.yml\n    with:\n      agent: ${{ needs.route.outputs.agent }}\n      number: ${{ needs.route.outputs.number }}\n      type: ${{ needs.route.outputs.type }}\n      notify: ${{ needs.route.outputs.notify }}\n    secrets: inherit\n",
      "tool_call_id": "call_bb3fc3e04c2d440586ddc99f"
    },
    {
      "role": "tool",
      "content": "name: Atoma Auto Trigger\n\n# Generic workflow triggered by GitHub events.\n# Uses pull_request_target (NOT pull_request) because GITHUB_TOKEN-created PRs\n# trigger the event but GitHub suppresses workflow runs for pull_request events.\n# pull_request_target runs in the base repo context with full write permissions.\n#\n# pull_request_review is handled in a separate workflow (atoma-pr-review.yml)\n# because pull_request_target and pull_request_review cannot be combined.\n\non:\n  pull_request_target:\n    types: [opened, synchronize, ready_for_review]\n\npermissions:\n  actions: write\n  issues: write\n  pull-requests: write\n  contents: write\n\njobs:\n  route:\n    runs-on: ubuntu-latest\n    outputs:\n      agent: ${{ steps.match.outputs.agent }}\n      number: ${{ steps.match.outputs.number }}\n      type: ${{ steps.match.outputs.type }}\n      notify: ${{ steps.notify.outputs.notify }}\n    steps:\n      # pull_request_target checks out the BASE ref by default — safe for config reads\n      - uses: actions/checkout@v4\n\n      - name: Determine PR number from event context\n        id: context\n        shell: bash\n        run: |\n          if [ -n \"${{ github.event.pull_request.number }}\" ]; then\n            echo \"number=${{ github.event.pull_request.number }}\" >> \"$GITHUB_OUTPUT\"\n            echo \"type=pr\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"number=${{ github.event.issue.number }}\" >> \"$GITHUB_OUTPUT\"\n            echo \"type=issue\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n      - name: Resolve notify login from PR body tag\n        id: notify\n        shell: bash\n        env:\n          PR_BODY: ${{ github.event.pull_request.body }}\n        run: |\n          NOTIFY=$(echo \"$PR_BODY\" | grep -oP '(?<=<!-- atoma:notify=)[A-Za-z0-9-]+(?= -->)' || true)\n          echo \"notify=${NOTIFY}\" >> \"$GITHUB_OUTPUT\"\n\n      - name: Match event to agent from config.json\n        id: match\n        shell: bash\n        env:\n          EVENT_TYPE: ${{ github.event_name }}.${{ github.event.action }}\n          REVIEW_STATE: ${{ github.event.review.state }}\n          IS_DRAFT: ${{ github.event.pull_request.draft }}\n        run: |\n          AGENT=$(python3 .github/atoma/tools/scripts/match_trigger.py 2>/dev/null || true)\n          if [ -n \"${AGENT}\" ]; then\n            echo \"Matched agent: ${AGENT}\"\n            echo \"agent=${AGENT}\" >> \"$GITHUB_OUTPUT\"\n            echo \"number=${{ steps.context.outputs.number }}\" >> \"$GITHUB_OUTPUT\"\n            echo \"type=${{ steps.context.outputs.type }}\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n  run:\n    needs: route\n    if: needs.route.outputs.agent != ''\n    uses: ./.github/workflows/atoma-runner.yml\n    with:\n      agent: ${{ needs.route.outputs.agent }}\n      number: ${{ needs.route.outputs.number }}\n      type: ${{ needs.route.outputs.type }}\n      notify: ${{ needs.route.outputs.notify }}\n    secrets: inherit\n",
      "tool_call_id": "call_7c8d3c882a4940fca5549953"
    },
    {
      "role": "tool",
      "content": "name: Atoma Manual Comment\n\n# Invoke agents via /agent-name slash command in issue/PR comments.\n# Restricted to OWNER/MEMBER/COLLABORATOR.\n\non:\n  issue_comment:\n    types: [created]\n\npermissions:\n  actions: write\n  issues: write\n  pull-requests: write\n  contents: write\n\njobs:\n  parse:\n    runs-on: ubuntu-latest\n    if: >-\n      (github.event.comment.user.type == 'Bot' &&\n       contains(github.event.comment.body, 'atoma:dispatch')) ||\n      (github.event.comment.user.type != 'Bot' &&\n       (github.event.comment.author_association == 'OWNER' ||\n        github.event.comment.author_association == 'MEMBER' ||\n        github.event.comment.author_association == 'COLLABORATOR'))\n    outputs:\n      agent: ${{ steps.command.outputs.agent }}\n      number: ${{ steps.target.outputs.number }}\n      type: ${{ steps.target.outputs.type }}\n      notify: ${{ steps.target.outputs.notify }}\n    steps:\n      - name: Parse slash command\n        id: command\n        uses: yuma-seno/atoma/github/actions/parse-comment-command@main\n        with:\n          body: ${{ github.event.comment.body }}\n\n      - name: Resolve target context\n        id: target\n        shell: bash\n        env:\n          NUMBER: ${{ github.event.issue.number }}\n          IS_PR: ${{ toJSON(github.event.issue.pull_request != null) }}\n          NOTIFY: ${{ github.event.comment.user.login }}\n        run: |\n          echo \"number=${NUMBER}\" >> \"$GITHUB_OUTPUT\"\n          if [ \"$IS_PR\" = \"true\" ]; then\n            echo \"type=pr\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"type=issue\" >> \"$GITHUB_OUTPUT\"\n          fi\n          echo \"notify=${NOTIFY}\" >> \"$GITHUB_OUTPUT\"\n\n  run:\n    needs: parse\n    if: needs.parse.outputs.agent != ''\n    uses: ./.github/workflows/atoma-runner.yml\n    with:\n      agent: ${{ needs.parse.outputs.agent }}\n      number: ${{ needs.parse.outputs.number }}\n      type: ${{ needs.parse.outputs.type }}\n      notify: ${{ needs.parse.outputs.notify }}\n    secrets: inherit\n",
      "tool_call_id": "call_25412a7a2db843a6b7bd41e4"
    },
    {
      "role": "tool",
      "content": "name: Atoma PR Merged\n\n# Detect PR merges and aggregate sub-issue results.\n# Uses pull_request_target so GITHUB_TOKEN-created PR merges are detected.\n#\n# This is the PRIMARY mechanism for sub-issue aggregation. It fires reliably\n# regardless of who/what merged the PR. The `issues: closed` event that also\n# fires when the merge auto-closes the linked issue is handled by\n# atoma-sub-issue-closed.yml, which explicitly skips issues closed via a merged\n# PR (see its \"Check if closed via a merged PR\" step) to avoid dispatching the\n# orchestrator twice for the same completion.\n\non:\n  pull_request_target:\n    types: [closed]\n\npermissions:\n  actions: write\n  issues: write\n  pull-requests: read\n  contents: write\n\njobs:\n  parse:\n    runs-on: ubuntu-latest\n    if: github.event.pull_request.merged == true\n    outputs:\n      parent_issue: ${{ steps.parent-issue.outputs.number }}\n      sub_issue: ${{ steps.sub-issue.outputs.number }}\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Parse parent issue from PR body\n        id: parent-issue\n        shell: bash\n        env:\n          PR_BODY: ${{ github.event.pull_request.body }}\n          PR_NUMBER: ${{ github.event.pull_request.number }}\n        run: |\n          PARENT=$(echo \"$PR_BODY\" | grep -oP '(?<=<!-- atoma:parent-issue=)\\d+(?= -->)' || true)\n          if [ -n \"$PARENT\" ]; then\n            echo \"number=${PARENT}\" >> \"$GITHUB_OUTPUT\"\n            echo \"PR #${PR_NUMBER} is linked to parent issue #${PARENT}\"\n          else\n            echo \"number=\" >> \"$GITHUB_OUTPUT\"\n            echo \"PR #${PR_NUMBER} has no parent-issue metadata\"\n          fi\n\n      - name: Parse sub-issue from PR body (Closes #N)\n        id: sub-issue\n        shell: bash\n        env:\n          PR_BODY: ${{ github.event.pull_request.body }}\n        run: |\n          SUB=$(echo \"$PR_BODY\" | grep -oP '(?<=Closes #)\\d+' | head -n1 || true)\n          if [ -n \"$SUB\" ]; then\n            echo \"number=${SUB}\" >> \"$GITHUB_OUTPUT\"\n            echo \"PR closes sub-issue #${SUB}\"\n          else\n            echo \"number=\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n  resolve-parent:\n    needs: parse\n    if: needs.parse.outputs.sub_issue != ''\n    runs-on: ubuntu-latest\n    outputs:\n      parent_issue: ${{ steps.resolve.outputs.parent_issue }}\n    steps:\n      - name: Resolve orchestrator parent via GraphQL parent field\n        id: resolve\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          SUB: ${{ needs.parse.outputs.sub_issue }}\n          OWNER: ${{ github.repository_owner }}\n          REPO: ${{ github.event.repository.name }}\n        run: |\n          PARENT=$(gh api graphql -f query='\n            query($owner:String!,$repo:String!,$num:Int!){\n              repository(owner:$owner,name:$repo){\n                issue(number:$num){parent{number}}\n              }\n            }' \\\n            -F owner=\"${OWNER}\" -F repo=\"${REPO}\" -F num=\"${SUB}\" \\\n            --jq '.data.repository.issue.parent.number' 2>/dev/null || true)\n          if [ -n \"$PARENT\" ] && [ \"$PARENT\" != \"null\" ]; then\n            echo \"parent_issue=${PARENT}\" >> \"$GITHUB_OUTPUT\"\n            echo \"Resolved via GraphQL parent: sub-issue #${SUB} → parent #${PARENT}\"\n          else\n            # Fallback: parse HTML comment from sub-issue body\n            BODY=$(gh issue view \"$SUB\" --repo \"${OWNER}/${REPO}\" --json body --jq '.body' 2>/dev/null || true)\n            PARENT=$(echo \"$BODY\" | grep -oP '(?<=<!-- atoma:parent=#)\\d+(?= -->)' || true)\n            echo \"parent_issue=${PARENT}\" >> \"$GITHUB_OUTPUT\"\n            [ -n \"$PARENT\" ] && echo \"Resolved via fallback: sub-issue #${SUB} → parent #${PARENT}\"\n          fi\n\n  notify-parent:\n    needs: [resolve-parent, parse]\n    if: needs.resolve-parent.outputs.parent_issue != ''\n    runs-on: ubuntu-latest\n    steps:\n      - name: Comment on parent issue\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          REPO: ${{ github.repository }}\n          PARENT: ${{ needs.resolve-parent.outputs.parent_issue }}\n          PR_NUMBER: ${{ github.event.pull_request.number }}\n          PR_TITLE: ${{ github.event.pull_request.title }}\n          PR_URL: ${{ github.event.pull_request.html_url }}\n        run: |\n          gh issue comment \"$PARENT\" --repo \"$REPO\" --body \\\n            \"PR #${PR_NUMBER} merged: ${PR_TITLE} (${PR_URL})\"\n\n  aggregate-sub-issues:\n    needs: [resolve-parent, parse]\n    if: needs.resolve-parent.outputs.parent_issue != ''\n    runs-on: ubuntu-latest\n    env:\n      GH_TOKEN: ${{ github.token }}\n      OWNER: ${{ github.repository_owner }}\n      REPO: ${{ github.event.repository.name }}\n      PARENT: ${{ needs.resolve-parent.outputs.parent_issue }}\n      CLOSED_NUM: ${{ needs.parse.outputs.sub_issue }}\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Aggregate sub-issue results\n        shell: bash\n        run: |\n          git config user.email \"action@github.com\"\n          git config user.name \"GitHub Actions\"\n\n          echo \"PR merged (sub-issue #${CLOSED_NUM}, parent #${PARENT}). Checking siblings...\"\n\n          SIBLING_COUNT=$(python3 .github/atoma/tools/scripts/check_open_siblings.py \\\n            --repo \"${OWNER}/${REPO}\" \\\n            --parent \"${PARENT}\")\n\n          if [ \"$SIBLING_COUNT\" -gt 0 ]; then\n            echo \"Still ${SIBLING_COUNT} open sibling(s). Notifying progress...\"\n            BD=$(mktemp)\n            echo \"<!-- atoma:sub-result:#${CLOSED_NUM} -->\" > \"$BD\"\n            echo \"Atoma: Sub-task #${CLOSED_NUM} completed. ${SIBLING_COUNT} sub-task(s) still in progress.\" >> \"$BD\"\n            gh issue comment \"${PARENT}\" --body-file \"$BD\"\n            rm -f \"$BD\"\n            echo \"Not all sub-tasks done yet.\"\n            exit 0\n          fi\n\n          echo \"All sub-tasks completed! Preparing orchestrator re-invocation...\"\n\n          ALL_SUBS=$(gh issue list \\\n            --repo \"${OWNER}/${REPO}\" \\\n            --state all \\\n            --json number,title,body \\\n            --jq \"[.[] | select(.body | contains(\\\"atoma:parent=#${PARENT}\\\")) | .number] | join(\\\",\\\")\" 2>/dev/null)\n\n          echo \"All sub-issues for parent #${PARENT}: ${ALL_SUBS}\"\n\n          SESSION_PATH=\"sessions/issue-${PARENT}-orchestrator.json\"\n\n          # Multiple parents can finish aggregation around the same time, all\n          # pushing to the same atoma-data branch, so a push race is expected,\n          # not exceptional. Re-pull the latest tip on every attempt and, if\n          # the push still loses the race, reset and retry from scratch --\n          # safe because each parent only ever touches its own uniquely-named\n          # SESSION_PATH, so a reset can never discard another parent's\n          # concurrently-pushed session.\n          SAVED=false\n          for attempt in 1 2 3 4 5; do\n            if git fetch origin atoma-data 2>/dev/null; then\n              git checkout -B atoma-data origin/atoma-data\n            else\n              git checkout --orphan atoma-data\n              git rm -rf . 2>/dev/null || true\n            fi\n\n            if git cat-file -e \"HEAD:${SESSION_PATH}\" 2>/dev/null; then\n              git show \"HEAD:${SESSION_PATH}\" > session.json\n            else\n              echo '{\"messages\":[]}' > session.json\n            fi\n\n            python3 .github/atoma/tools/scripts/inject_sub_results.py \\\n              --session session.json \\\n              --repo \"${OWNER}/${REPO}\" \\\n              --parent \"${PARENT}\" \\\n              --sub-issues \"${ALL_SUBS}\" \\\n              --out session.json\n\n            mkdir -p \"$(dirname \"${SESSION_PATH}\")\"\n            mv session.json \"${SESSION_PATH}\"\n            git add \"${SESSION_PATH}\"\n\n            if git diff --cached --quiet; then\n              echo \"No changes to session; skipping commit.\"\n              SAVED=true\n              break\n            fi\n\n            git commit -m \"atoma: inject sub-issue results for parent #${PARENT}\"\n\n            if git push origin atoma-data; then\n              SAVED=true\n              break\n            fi\n\n            echo \"Push attempt ${attempt} failed (concurrent push) -- resetting and retrying with a fresh pull...\"\n            sleep $((attempt * 2))\n          done\n\n          if [ \"$SAVED\" != \"true\" ]; then\n            echo \"::warning::Failed to save session to atoma-data:${SESSION_PATH} after all retries.\"\n          fi\n\n          BD=$(mktemp)\n          echo \"<!-- atoma:sub-result:#${CLOSED_NUM} -->\" > \"$BD\"\n          echo \"Atoma: All sub-tasks completed. Re-starting orchestrator for aggregation.\" >> \"$BD\"\n          gh issue comment \"${PARENT}\" --body-file \"$BD\"\n          rm -f \"$BD\"\n\n          NOTIFY=$(python3 .github/atoma/tools/scripts/resolve_notify.py \\\n            --repo \"${OWNER}/${REPO}\" --number \"${PARENT}\")\n          gh workflow run \"atoma-runner.yml\" \\\n            --field agent=\"orchestrator\" \\\n            --field number=\"${PARENT}\" \\\n            --field type=\"issue\" \\\n            --field notify=\"${NOTIFY}\"",
      "tool_call_id": "call_f51d886cb1a74d399dd7ceba"
    },
    {
      "role": "tool",
      "content": "name: Atoma PR Review\n\n# Separate workflow for pull_request_review events.\n# Cannot be combined with pull_request_target in atoma-auto-trigger.yml.\n\non:\n  pull_request_review:\n    types: [submitted]\n\npermissions:\n  actions: write\n  issues: write\n  pull-requests: write\n  contents: write\n\njobs:\n  route:\n    runs-on: ubuntu-latest\n    outputs:\n      agent: ${{ steps.match.outputs.agent }}\n      number: ${{ steps.match.outputs.number }}\n      type: ${{ steps.match.outputs.type }}\n      notify: ${{ steps.notify.outputs.notify }}\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Determine PR number\n        id: context\n        shell: bash\n        run: |\n          echo \"number=${{ github.event.pull_request.number }}\" >> \"$GITHUB_OUTPUT\"\n          echo \"type=pr\" >> \"$GITHUB_OUTPUT\"\n\n      - name: Resolve notify login from PR body tag\n        id: notify\n        shell: bash\n        env:\n          PR_BODY: ${{ github.event.pull_request.body }}\n        run: |\n          NOTIFY=$(echo \"$PR_BODY\" | grep -oP '(?<=<!-- atoma:notify=)[A-Za-z0-9-]+(?= -->)' || true)\n          echo \"notify=${NOTIFY}\" >> \"$GITHUB_OUTPUT\"\n\n      - name: Match event to agent from config.json\n        id: match\n        shell: bash\n        env:\n          EVENT_TYPE: ${{ github.event_name }}.${{ github.event.action }}\n          REVIEW_STATE: ${{ github.event.review.state }}\n        run: |\n          AGENT=$(python3 .github/atoma/tools/scripts/match_trigger.py 2>/dev/null || true)\n          if [ -n \"${AGENT}\" ]; then\n            echo \"Matched agent: ${AGENT}\"\n            echo \"agent=${AGENT}\" >> \"$GITHUB_OUTPUT\"\n            echo \"number=${{ steps.context.outputs.number }}\" >> \"$GITHUB_OUTPUT\"\n            echo \"type=${{ steps.context.outputs.type }}\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n  run:\n    needs: route\n    if: needs.route.outputs.agent != ''\n    uses: ./.github/workflows/atoma-runner.yml\n    with:\n      agent: ${{ needs.route.outputs.agent }}\n      number: ${{ needs.route.outputs.number }}\n      type: ${{ needs.route.outputs.type }}\n      notify: ${{ needs.route.outputs.notify }}\n    secrets: inherit",
      "tool_call_id": "call_31f55810d9b84cfa96012dff"
