      "role": "tool",
      "content": "name: Atoma Sub-Issue Closed\n\n# FALLBACK for manually closed sub-issues.\n# Primary aggregation happens in atoma-pr-merged.yml (pull_request_target).\n# This handles the case where a human closes a sub-issue manually.\n\non:\n  issues:\n    types: [closed]\n\npermissions:\n  actions: write\n  issues: write\n  pull-requests: write\n  contents: write\n\njobs:\n  check:\n    runs-on: ubuntu-latest\n    outputs:\n      is_sub_issue: ${{ steps.parse.outputs.is_sub_issue }}\n      parent_number: ${{ steps.parse.outputs.parent_number }}\n      closed_via_pr: ${{ steps.pr-check.outputs.closed_via_pr }}\n    steps:\n      - name: Parse parent reference from issue body\n        id: parse\n        shell: bash\n        env:\n          CLOSED_NUM: ${{ github.event.issue.number }}\n        run: |\n          BODY=$(jq -r '.issue.body // \"\"' \"$GITHUB_EVENT_PATH\")\n          PARENT=$(echo \"$BODY\" | grep -oP '(?<=<!-- atoma:parent=#)\\d+(?= -->)' || true)\n          if [ -n \"$PARENT\" ]; then\n            echo \"is_sub_issue=true\" >> \"$GITHUB_OUTPUT\"\n            echo \"parent_number=${PARENT}\" >> \"$GITHUB_OUTPUT\"\n            echo \"Sub-issue #${CLOSED_NUM} closed — parent #${PARENT}\"\n          else\n            echo \"is_sub_issue=false\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n      # atoma-pr-merged.yml (pull_request_target: closed) is the PRIMARY aggregation\n      # path and already handles sub-issues auto-closed by a merged PR's \"Closes #N\".\n      # A merged PR's auto-close ALSO fires this `issues: closed` event (GitHub only\n      # suppresses that cascade for GITHUB_TOKEN-driven merges — under the default\n      # merge_policy: \"manual\", a human/agent merges via their own credentials, so\n      # both workflows fire). Without this check, the orchestrator gets dispatched\n      # twice. Skip here whenever a merged PR already closed the issue.\n      - name: Check if closed via a merged PR\n        id: pr-check\n        if: steps.parse.outputs.is_sub_issue == 'true'\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          OWNER: ${{ github.repository_owner }}\n          REPO: ${{ github.event.repository.name }}\n          CLOSED_NUM: ${{ github.event.issue.number }}\n        run: |\n          MERGED_PR=$(gh api graphql -f query='\n            query($owner:String!,$repo:String!,$num:Int!){\n              repository(owner:$owner,name:$repo){\n                issue(number:$num){\n                  closedByPullRequestsReferences(first: 1) { nodes { number } }\n                }\n              }\n            }' -F owner=\"${OWNER}\" -F repo=\"${REPO}\" -F num=\"${CLOSED_NUM}\" \\\n            --jq '.data.repository.issue.closedByPullRequestsReferences.nodes[0].number // \"\"' 2>/dev/null || true)\n          if [ -n \"$MERGED_PR\" ]; then\n            echo \"Closed via merged PR #${MERGED_PR} — already handled by atoma-pr-merged.yml. Skipping.\"\n            echo \"closed_via_pr=true\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"closed_via_pr=false\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n  aggregate:\n    needs: check\n    if: needs.check.outputs.is_sub_issue == 'true' && needs.check.outputs.closed_via_pr != 'true'\n    runs-on: ubuntu-latest\n    env:\n      GH_TOKEN: ${{ github.token }}\n      OWNER: ${{ github.repository_owner }}\n      REPO: ${{ github.event.repository.name }}\n      PARENT: ${{ needs.check.outputs.parent_number }}\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Check siblings and re-trigger orchestrator\n        shell: bash\n        run: |\n          echo \"Sub-issue closed manually. Checking open siblings...\"\n          SIBLING_COUNT=$(python3 .github/atoma/tools/scripts/check_open_siblings.py \\\n            --repo \"${OWNER}/${REPO}\" \\\n            --parent \"${PARENT}\")\n\n          if [ \"$SIBLING_COUNT\" -gt 0 ]; then\n            echo \"Still ${SIBLING_COUNT} sibling(s) open. No action needed.\"\n            exit 0\n          fi\n\n          echo \"All siblings done. Dispatching orchestrator on parent #${PARENT} ...\"\n          # atoma-runner.yml only actually runs the agent when new_event_count != '0'\n          # (a hash comparison of the parent issue's own body+comments against the\n          # orchestrator's last processed snapshot). Without a new comment on the\n          # parent itself, the dispatched run would just no-op as \"skipped\" -- post\n          # one here first, same as atoma-pr-merged.yml's aggregate-sub-issues job.\n          gh issue comment \"${PARENT}\" --repo \"${OWNER}/${REPO}\" --body \\\n            \"All sub-tasks completed. Re-invoking orchestrator for aggregation.\"\n          NOTIFY=$(python3 .github/atoma/tools/scripts/resolve_notify.py \\\n            --repo \"${OWNER}/${REPO}\" --number \"${PARENT}\")\n          gh workflow run \"atoma-runner.yml\" \\\n            --field agent=\"orchestrator\" \\\n            --field number=\"${PARENT}\" \\\n            --field type=\"issue\" \\\n            --field notify=\"${NOTIFY}\"",
