\n      - name: Create feature branch for issue\n        if: inputs.type == 'issue'\n        shell: bash\n        run: |\n          BRANCH=\"atoma/issue-${{ inputs.number }}\"\n          git checkout -b \"$BRANCH\" 2>/dev/null || git checkout \"$BRANCH\"\n          echo \"BRANCH=$BRANCH\" >> $GITHUB_ENV\n\n      - name: Set branch env for PR type\n        if: inputs.type != 'issue'\n        shell: bash\n        run: |\n          echo \"BRANCH=$(git rev-parse --abbrev-ref HEAD)\" >> $GITHUB_ENV\n\n      - name: Setup runtime\n        uses: yuma-seno/atoma/github/actions/setup-runtime@main\n\n      - name: Run configured environment setup\n        # Generic hook, NOT Python/pytest-specific: runs whatever shell commands\n        # are declared in config.json's `environment.setup_commands` (if any)\n        # before the agent starts, so it never has to spend iterations/tool\n        # calls doing one-off environment prep itself (e.g. installing a test\n        # runner) on a cold runner. Leave `environment.setup_commands` empty or\n        # unset in config.json if your project needs no such step.\n        shell: bash\n        run: |\n          python3 - <<'PY' > /tmp/_setup_commands.txt\n          import json\n          from pathlib import Path\n\n          path = Path(\".github/atoma/config.json\")\n          commands = []\n          if path.exists():\n              config = json.loads(path.read_text(encoding=\"utf-8\"))\n              env = config.get(\"environment\") or {}\n              commands = env.get(\"setup_commands\") or []\n          for cmd in commands:\n              print(cmd)\n          PY\n          if [ -s /tmp/_setup_commands.txt ]; then\n            while IFS= read -r cmd; do\n              echo \"Running environment setup command: ${cmd}\"\n              bash -c \"$cmd\"\n            done < /tmp/_setup_commands.txt\n          else\n            echo \"No environment.setup_commands configured; skipping.\"\n          fi\n          rm -f /tmp/_setup_commands.txt\n\n      - name: Configure git identity\n        shell: bash\n        run: |\n          git config user.name \"atoma-${{ inputs.agent }}\"\n          git config user.email \"atoma-${{ inputs.agent }}@users.noreply.github.com\"\n\n      - name: Resolve effective notify login\n        # Defense in depth: inputs.notify *should* already carry the human to\n        # ping (see resolve_notify.py / atoma:notify= tag propagation), but if\n        # it ever arrives empty (a missed dispatch path, a new caller that\n        # forgot to wire it, etc.) we do a live fallback lookup here so a run\n        # that ends with neither a next-agent directive nor a notify never\n        # goes completely silent. Cheap no-op when notify is already set.\n        id: notify\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          NOTIFY: ${{ inputs.notify }}\n          NUMBER: ${{ inputs.number }}\n        run: |\n          EFFECTIVE=\"$NOTIFY\"\n          if [ -z \"$EFFECTIVE\" ]; then\n            EFFECTIVE=$(python3 .github/atoma/tools/scripts/resolve_notify.py --repo \"${GITHUB_REPOSITORY}\" --number \"${NUMBER}\")\n            [ -n \"$EFFECTIVE\" ] && echo \"Resolved notify fallback: ${EFFECTIVE}\"\n          fi\n          echo \"notify=${EFFECTIVE}\" >> \"$GITHUB_OUTPUT\"\n\n      - name: Prepare shared context\n        id: prep\n        uses: yuma-seno/atoma/github/actions/prepare@main\n        with:\n          type: ${{ inputs.type }}\n          number: ${{ inputs.number }}\n          agent_name: ${{ inputs.agent }}\n          orchestration_file: .github/atoma/config.json\n\n      - name: Read max_iterations from config\n        id: cfg\n        shell: bash\n        env:\n          AGENT_NAME: ${{ inputs.agent }}\n        run: |\n          MAX=$(python3 .github/atoma/tools/scripts/get_config_value.py \"agents.${AGENT_NAME}.max_iterations\" 30)\n          echo \"max_iterations=${MAX}\" >> \"$GITHUB_OUTPUT\"\n          echo \"Agent ${AGENT_NAME} max_iterations: ${MAX}\"\n\n      - name: Add atoma/in-progress label\n        # Added BEFORE the agent actually runs (not after) so it's visible to a\n        # human for the entire duration of the run, not just flickered on/off\n        # afterwards. Applies to both issues and PRs -- `gh issue edit` works on\n        # PR numbers too since GitHub treats every PR as an issue under the hood.\n        # Gated on the same condition as \"Run agent\" so the label isn't added\n        # for no-op runs that will be skipped entirely (new_event_count == '0').\n        if: steps.prep.outputs.new_event_count != '0'\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          NUMBER: ${{ inputs.number }}\n        run: |\n          LABEL=$(python3 .github/atoma/tools/scripts/get_config_value.py \"labels.in_progress\" \"atoma/in-progress\")\n          # Create the label if it does not exist yet\n          gh label create \"$LABEL\" --force \\\n            -c '0366d6' \\\n            -d 'Issue is being worked on by an Atoma agent' 2>/dev/null || true\n          gh issue edit \"$NUMBER\" --add-label \"$LABEL\" 2>/dev/null || true\n\n      - name: Run agent\n        if: steps.prep.outputs.new_event_count != '0'\n        id: atoma\n        uses: yuma-seno/atoma/github/actions/run@main\n        with:\n          agent_name: ${{ inputs.agent }}\n          agent_def_dir: .github/atoma/agent-definitions\n          tools_file: .github/atoma/tools/tools.yaml\n          issue_number: ${{ steps.prep.outputs.resolved_number }}\n          orchestration_file: .github/atoma/config.json\n          atoma_version: ${{ inputs.atoma_version }}\n          max_iterations: ${{ steps.cfg.outputs.max_iterations }}\n          notify_login: ${{ steps.notify.outputs.notify }}\n          openai_api_key: ${{ secrets.OPENAI_API_KEY }}\n          openai_base_url: ${{ vars.OPENAI_BASE_URL }}\n          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}\n          atoma_provider: ${{ vars.ATOMA_PROVIDER }}\n\n      - name: Remove atoma/in-progress label on completion\n        # Remove atoma/in-progress when the agent run finishes (success or failure).\n        # Sub-issues keep atoma/sub-issue label for tracking (never removed here).\n        # Applies to both issues and PRs, mirroring the Add step above.\n        if: always()\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          NUMBER: ${{ inputs.number }}\n        run: |\n          LABEL=$(python3 .github/atoma/tools/scripts/get_config_value.py \"labels.in_progress\" \"atoma/in-progress\")\n          gh issue edit \"$NUMBER\" --remove-label \"$LABEL\" 2>/dev/null || true\n\n      - name: Post result\n        # post-result's own inner guard (atoma_outcome == 'success' && new_event_count\n        # != '0') is sufficient: it always posts the agent's final response as a\n        # comment when the run actually did something. Do NOT gate the comment\n        # itself on `directive` being empty -- that shape is indistinguishable from\n        # a normal \"nothing more to do\" completion AND from an important final\n        # summary (e.g. orchestrator aggregation), so gating on it would silently\n        # drop real summaries/notifications instead of just reducing noise.\n        # The \"please review\" notice inside post-result is separately suppressed\n        # via `chain_continues` (set when a tool call, e.g. launch_sub_agent or\n        # create_pr, already triggered an automatic follow-up run) -- that is a\n        # purpose-built signal, not a reuse of the ambiguous `directive` emptiness.\n        if: always()\n        uses: yuma-seno/atoma/github/actions/post-result@main\n        with:\n          agent_name: ${{ inputs.agent }}\n          number: ${{ inputs.number }}\n          type: ${{ inputs.type }}\n          notify: ${{ steps.notify.outputs.notify }}\n          job_status: ${{ job.status }}\n          atoma_outcome: ${{ steps.atoma.outcome }}\n          new_event_count: ${{ steps.prep.outputs.new_event_count }}\n          context_snapshot_hash: ${{ steps.prep.outputs.context_snapshot_hash }}\n          context_event_count: ${{ steps.prep.outputs.context_event_count }}\n          resolved_number: ${{ steps.prep.outputs.resolved_number }}\n          directive: ${{ steps.atoma.outputs.directive }}\n          max_iterations_reached: ${{ steps.atoma.outputs.max_iterations_reached }}\n          chain_continues: ${{ steps.atoma.outputs.chain_continues }}\n\n      - name: Check for uncommitted changes\n        id: dirty\n        if: steps.atoma.outcome == 'success'\n        shell: bash\n        run: |\n          if [ -n \"$(git status --porcelain)\" ]; then\n            echo \"has_changes=true\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n      - name: Inject uncommitted changes into session\n        if: steps.dirty.outputs.has_changes == 'true'\n        shell: bash\n        run: |\n          SESSION=$(find . -maxdepth 3 -name 'session.json' 2>/dev/null | head -1)\n          if [ -n \"$SESSION\" ] && [ -f \"$SESSION\" ]; then\n            printf 'import json\\ns=json.load(open(\"%s\"))\\ns[\"messages\"].append({\"role\":\"user\",\"content\":\"Uncommitted changes exist. Use github__commit_and_push.\"})\\njson.dump(s,open(\"%s\",\"w\"),indent=2)\\n' \"$SESSION\" \"$SESSION\" > /tmp/_inj.py\n            python3 /tmp/_inj.py\n          fi\n\n      - name: Notify on max iterations\n        if: steps.atoma.outputs.max_iterations_reached == 'true'\n        shell: bash\n        env:\n          GH_TOKEN: ${{ github.token }}\n          NUMBER: ${{ inputs.number }}\n          NOTIFY: ${{ steps.notify.outputs.notify }}\n          AGENT: ${{ inputs.agent }}\n        run: |\n          if [ -n \"$NOTIFY\" ]; then\n            gh issue comment \"$NUMBER\" --body \"@${NOTIFY} Atoma: \\`${AGENT}\\` reached the max iteration limit. Review the issue and comment \\`/${AGENT}\\` to retry.\"\n          else\n            gh issue comment \"$NUMBER\" -