w events or outcome is not success\\n        if [ \\\"${NEW_EVENT_COUNT}\\\" = \\\"0\\\" ]; then\\n          echo \\\"No new events; skipping dispatch.\\\"\\n          exit 0\\n        fi\\n\\n        if [ \\\"${ATOMA_OUTCOME}\\\" != \\\"success\\\" ]; then\\n          echo \\\"Agent did not complete successfully; skipping dispatch.\\\"\\n          exit 0\\n        fi\\n\\n        # If max iterations reached, skip dispatch\\n        if [ \\\"${MAX_ITER}\\\" = \\\"true\\\" ]; then\\n          echo \\\"Max iterations reached; skipping dispatch.\\\"\\n          exit 0\\n        fi\\n\\n        # Check for a next-agent directive\\n        NEXT_AGENT=\\\"\\\"\\n        if [ -n \\\"${DIRECTIVE}\\\" ]; then\\n          NEXT_AGENT=\\\"${DIRECTIVE}\\\"\\n          echo \\\"Using directive: ${NEXT_AGENT}\\\"\\n        fi\\n\\n        # If no directive, check ops log for create_pr\\n        if [ -z \\\"${NEXT_AGENT}\\\" ]; then\\n          if [ -f /tmp/atoma_ops.log ]; then\\n            LAST_OP=$(tail -1 /tmp/atoma_ops.log 2>/dev/null | python3 -c \\\"\\nimport json, sys\\ntry:\\n    d = json.load(sys.stdin)\\n    print(d.get('op', ''))\\nexcept:\\n    print('')\\n\\\" 2>/dev/null || echo \\\"\\\")\\n            if [ \\\"${LAST_OP}\\\" = \\\"create_pr\\\" ]; then\\n              echo \\\"create_pr detected; no further dispatch needed (reviewer auto-triggered).\\\"\\n              exit 0\\n            fi\\n          fi\\n        fi\\n\\n        # If we have a next agent, dispatch\\n        if [ -n \\\"${NEXT_AGENT}\\\" ]; then\\n          echo \\\"Dispatching next agent: ${NEXT_AGENT} on ${TYPE} #${NUMBER}\\\"\\n          NOTIFY_ARG=\\\"\\\"\\n          if [ -n \\\"${NOTIFY}\\\" ]; then\\n            NOTIFY_ARG=\\\"--field notify=${NOTIFY}\\\"\\n          fi\\n          gh workflow run \\\"atoma-runner.yml\\\" \\\\\\n            --repo \\\"${GITHUB_REPOSITORY}\\\" \\\\\\n            --field \\\"agent=${NEXT_AGENT}\\\" \\\\\\n            --field \\\"number=${NUMBER}\\\" \\\\\\n